'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs/promises');
const os = require('node:os');
const path = require('node:path');
const { openArchive, writeArchive } = require('./offline-archive.cjs');
// Independently generated with Python zipfile (deflate), containing the known
// 70-byte 1x1 PNG. This is not generated by the production writer being tested.
const fixture = Buffer.from('UEsDBBQAAAAIAFK0RF05YQprPwAAAEYAAAAFAAAAMi5wbmfrDPBz5+WS4mJgYOD19HAJAtKMIMzBBiTlRY90giVcHEMq5iT/OH/ggzwDKwPj/86ZtrJACQZPVz+XdU4JTQBQSwECFAMUAAAACABStERdOWEKaz8AAABGAAAABQAAAAAAAAAAAAAAgAEAAAAAMi5wbmdQSwUGAAAAAAEAAQAzAAAAYgAAAAAA', 'base64');
const png = Buffer.from('iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR4nGP4z8DwHwAFAAH/iZk9HQAAAABJRU5ErkJggg==', 'base64');
async function temporary(t) { const root = await fs.mkdtemp(path.join(os.tmpdir(), 'nyora-zip-test-')); t.after(() => fs.rm(root, { recursive: true, force: true })); return root; }
test('bounded ZIP reader accepts an independent deflate archive and checks its literal CRC', async t => {
  const file = path.join(await temporary(t), 'fixture.cbz'); await fs.writeFile(file, fixture);
  const archive = await openArchive(file);
  try { assert.equal(archive.entries[0].name, '2.png'); assert.equal(archive.entries[0].crc, 0x6b0a6139); assert.deepEqual(await archive.read(archive.entries[0]), png); }
  finally { await archive.close(); }
});
test('archive traversal, encryption, symlinks, unsupported methods and inflated-size bombs are rejected', async t => {
  const root = await temporary(t), central = fixture.indexOf(Buffer.from('PK\x01\x02'));
  const changes = [
    bytes => { bytes.write('../xx', 30); bytes.write('../xx', central + 46); },
    bytes => bytes.writeUInt16LE(1, central + 8),
    bytes => bytes.writeUInt32LE(0xa1ff0000, central + 38),
    bytes => bytes.writeUInt16LE(99, central + 10),
    bytes => bytes.writeUInt32LE(1024 * 1024 * 1024, central + 24),
  ];
  for (const [index, change] of changes.entries()) {
    const bytes = Buffer.from(fixture); change(bytes); const file = path.join(root, `${index}.cbz`); await fs.writeFile(file, bytes);
    await assert.rejects(openArchive(file));
  }
});
test('damaged CRC and truncation never return a page, output bounds hold before inflate', async t => {
  const root = await temporary(t), file = path.join(root, 'fixture.cbz'); await fs.writeFile(file, fixture);
  const archive = await openArchive(file);
  try { await assert.rejects(archive.read(archive.entries[0], 32)); }
  finally { await archive.close(); }
  const wrong = Buffer.from(fixture), central = wrong.indexOf(Buffer.from('PK\x01\x02')); wrong.writeUInt32LE(1, central + 16); await fs.writeFile(file, wrong);
  const damaged = await openArchive(file); try { await assert.rejects(damaged.read(damaged.entries[0]), /damaged/); } finally { await damaged.close(); }
  await fs.writeFile(file, fixture.subarray(0, -1)); await assert.rejects(openArchive(file));
});
test('streaming stored writer preserves exact page bytes and valid ZIP central sizes', async t => {
  const root = await temporary(t), page = path.join(root, 'page.png'), file = path.join(root, 'result.cbz'); await fs.writeFile(page, png);
  await writeArchive(file, [{ name: '0001.png', path: page }]);
  const archive = await openArchive(file); try {
    assert.equal(archive.entries[0].length, 70); assert.equal(archive.entries[0].crc, 0x6b0a6139); assert.deepEqual(await archive.read(archive.entries[0]), png);
  } finally { await archive.close(); }
});
